  "host_observations": [
    {"host": "WS-IT-31.corp.local", "role": "endpoint", "user": "r.singh", "victim_ip": "10.40.55.131", "target_dc": "DC-CORP-01.corp.local", "first_seen": "2033-08-04T14:18:08+0000", "last_seen": "2033-08-04T14:23:00+0000"}
